"""
This module provides the `emil` class which is a Robot Framework library for creating and managing Emil Converters.

Classes:
    emil: A Robot Framework library for creating and managing Emil Converters.

:copyright: Nokia Networks
:author: Prashant Gurjar
:contact: prashant.gurjar@nokia.com
:maintainer: Prashant Gurjar
:contact: prashant.gurjar@nokia.com
"""
import logging
from taf.converters.base import base
from robot.utils.robottypes import is_truthy
from .factory import (EmilConverterForCallsFactory,
                      EmilConverterForSourceFactory,
                      EmilConverterForCallFactory)

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class emil(base):
    """
    A Robot Framework library for creating and managing Emil Converters.

    This class provides a methods for creating a new Emil Converter with the given configuration.

    Attributes:
        ROBOT_LIBRARY_SCOPE (str): The scope of this Robot Framework library. Set to 'TEST SUITE'.

    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    _factory = {'source': EmilConverterForSourceFactory(),
                'calls': EmilConverterForCallsFactory(),
                'call': EmilConverterForCallFactory()}

    def _create_emil_converter(self, name, file_path_pattern, server_filter, client_filter, output_type,
                               output_directory, uploading_timeout, decoding_timeout, converter_type, dcap=None,
                               trace_id=None):
        if dcap:
            dcap.update({'port': int(dcap['port'])} if 'port' in dcap else {})
            dcap.update({'secure': is_truthy(dcap['secure'])} if 'secure' in dcap else {})
        configuration = {
            'name': name,
            'server_filter': server_filter,
            'client_filter': client_filter,
            'file_path_pattern': file_path_pattern,
            'dcap': dcap,
            'output_type': output_type,
            'output_directory': output_directory,
            'uploading_timeout': int(uploading_timeout) if uploading_timeout else None,
            'decoding_timeout': int(decoding_timeout) if decoding_timeout else None,
            'trace_id': int(trace_id) if trace_id is not None else None
        }
        configuration = {key: value for key, value in configuration.items() if value is not None}
        logger.info(f"Creating Emil Converter of {converter_type} type with alias: {name}")
        converter = self._factory[converter_type].create(
            configuration=configuration,
            existing_arguments={})
        logger.info(f"{name} converter created successfully")
        self.set_alias(name, converter)

    def create_emil_converter_for_source(
            self,
            name,
            file_path_pattern,
            server_filter=None,
            client_filter=None,
            output_type=None,
            output_directory=None,
            uploading_timeout=None,
            decoding_timeout=None,
            dcap=None):
        """
        Creates a new Emil Converter for source with the given configuration.

        Args:
            :param str name: The name of the new Emil Converter.
            :param str file_path_pattern: The input file path pattern to use for the Emil Converter. It should have
                                            \\*.5gm files for a single capturing session for one BTS. In case for one
                                            dcap.zip file have multiple BTS/vCU/vDU \\*.5gm files, multiple converter
                                            need to be created (One converter for one node).
            :param Optional[list] server_filter: The filter to use for the Emil Converter. For more details on the
                                                 filter syntax please refer 'filter' parameter description from
                                                 `get_decoded_file_contents_in_csv <https://taf-sw-dcap-rd.docs.taf.ute\
                                                 .nsn-rdnet.net/en/latest/interfaces/interface.html#taf.sw.dcap.rd\
                                                 .interface.rd.get_decoded_file_contents_in_csv>`_ keyword.
            :param Optional[Callable[[dict],bool]] client_filter: Callable function as which can take decoded Emil
                                                                  row dict as input and return True, if the row shall be
                                                                  kept.
            :param Optional[str] output_type: The output type for the Emil Converter. Defaults to 'json'.
            :param Optional[str] output_directory: The output directory for the Emil Converter. Default is directory
                                                   part of input file path pattern. Output file name will be
                                                   <source_id>_source.<json/csv>
            :param Optional[int] uploading_timeout: The timeout for the uploading trace file in seconds.
                                                    Defaults to 60 sec.
            :param Optional[int] decoding_timeout: The timeout for the decoding trace file in seconds.
                                                   Defaults to 30 sec.
            :param Optional[dict] dcap: The `dcap` parameter is a dictionary that allows to configure non-default
                                        DCAP (=UTF Lab) settings for the Emil Converter. If not provided, the default
                                        values will be used. The keys for this dictionary can include:

                - `host`: The host address of the DCAP server. Default is "127.0.0.1".
                - `port`: The port number for the DCAP server. Default is 9443.
                - `secure`: A boolean value indicating whether to use a secure connection. Default is True.
                - `username`: The username for the DCAP server. Default is None.
                - `password`: The password for the DCAP server. Default is None.

                Please refer `connect_to <https://taf-sw-dcap-rd.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/\
                interface.html#taf.sw.dcap.rd.interface.rd.connect_to>`_ keyword for other supported parameters.

        Returns:
            None
        """
        self._create_emil_converter(name=name, file_path_pattern=file_path_pattern, server_filter=server_filter,
                                    client_filter=client_filter, output_type=output_type,
                                    output_directory=output_directory, uploading_timeout=uploading_timeout,
                                    decoding_timeout=decoding_timeout, dcap=dcap, converter_type='source')

    def create_emil_converter_for_calls(
            self,
            name,
            file_path_pattern,
            server_filter=None,
            client_filter=None,
            output_type=None,
            output_directory=None,
            uploading_timeout=None,
            decoding_timeout=None,
            dcap=None):
        """
        Creates a new Emil Converter for calls with the given configuration.

        Args:
            :param str name: The name of the new Emil Converter.
            :param str file_path_pattern: The input file path pattern to use for the Emil Converter. It should have
                                            \\*.5gm files for a single capturing session for one BTS. In case for one
                                            dcap.zip file have multiple BTS/vCU/vDU \\*.5gm files, multiple converters
                                            need to be created (One converter for one node).
            :param Optional[list] server_filter: The filter to use for the Emil Converter. For more details on
                                                 the filter syntax please refer 'filter' parameter description
                                                 from `get_decoded_file_contents_in_csv <https://taf-sw-dcap-\
                                                 rd.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/interface\
                                                 .html#taf.sw.dcap.rd.interface.rd.get_decoded_file_contents_\
                                                 in_csv>`_ keyword.
            :param Optional[Callable[[dict],bool]] client_filter: Callable function as which can take decoded Emil
                                                                  row dict as input and return True, if the row shall be
                                                                  kept.
            :param Optional[str] output_type: The output type for the Emil Converter. Defaults to 'json'.
            :param Optional[str] output_directory: The output directory for the Emil Converter. Defaults same as input
                                                   file path. Output file name will be <grid_id>_calls.<json/csv>
            :param Optional[int] uploading_timeout: The timeout for the uploading trace file in seconds.
                                                    Defaults to 60 sec.
            :param Optional[int] decoding_timeout: The timeout for the decoding trace file in seconds.
                                                   Defaults to 30 sec.
            :param Optional[dict] dcap: The `dcap` parameter is a dictionary that allows to configure non-default DCAP
                                        settings for the Emil Converter. If not provided, the default values will be
                                        used. The keys for this dictionary can include:

                - `host`: The host address of the DCAP server. Default is "127.0.0.1".
                - `port`: The port number for the DCAP server. Default is 9443.
                - `secure`: A boolean value indicating whether to use a secure connection. Default is True.
                - `username`: The username for the DCAP server. Default is None.
                - `password`: The password for the DCAP server. Default is None.

                Please refer `connect_to <https://taf-sw-dcap-rd.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/\
                interface.html#taf.sw.dcap.rd.interface.rd.connect_to>`_ keyword for other supported parameters.

        Returns:
            None
        """
        self._create_emil_converter(name=name, file_path_pattern=file_path_pattern, server_filter=server_filter,
                                    client_filter=client_filter, output_type=output_type,
                                    output_directory=output_directory, uploading_timeout=uploading_timeout,
                                    decoding_timeout=decoding_timeout, dcap=dcap, converter_type='calls')

    def create_emil_converter_for_call(
            self,
            name,
            file_path_pattern,
            trace_id,
            server_filter=None,
            client_filter=None,
            output_type=None,
            output_directory=None,
            uploading_timeout=None,
            decoding_timeout=None,
            dcap=None):
        """
        Creates a new Emil Converter for trace_id with the given configuration.

        Args:
            :param str name: The name of the new Emil Converter.
            :param str file_path_pattern: The input file path pattern to use for the Emil Converter. It should have
                                            \\*.5gm files for a single capturing session for one BTS. In case for one
                                            dcap.zip file have multiple BTS/vCU/vDU \\*.5gm files, multiple converter
                                            need to be created (One converter for one node).
            :param Union[int,str] trace_id: The trace_id to use for the Emil Converter.
            :param Optional[list] server_filter: The filter to use for the Emil Converter. For more details on
                                                 the filter syntax please refer 'filter' parameter description
                                                 from `get_decoded_file_contents_in_csv <https://taf-sw-dcap-\
                                                 rd.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/interface\
                                                 .html#taf.sw.dcap.rd.interface.rd.get_decoded_file_contents_\
                                                 in_csv>`_ keyword.
            :param Optional[Callable[[dict],bool]] client_filter: Callable function as which can take decoded Emil
                                                                  row dict as input and return True, if the row shall be
                                                                  kept.
            :param Optional[str] output_type: The output type for the Emil Converter. Defaults to 'json'.
            :param Optional[str] output_directory: The output directory for the Emil Converter. Defaults same as input
                                                   file path. Output file name will be <grid_id>_<trace_id>.<json/csv>
            :param Optional[int] uploading_timeout: The timeout for the uploading trace file in seconds.
                                                    Defaults to 60 sec.
            :param Optional[int] decoding_timeout: The timeout for the decoding trace file in seconds.
                                                   Defaults to 30 sec.
            :param Optional[dict] dcap: The `dcap` parameter is a dictionary that allows to configure non-default DCAP
                                        settings for the Emil Converter. If not provided, the default values will be
                                        used. The keys for this dictionary can include:

                - `host`: The host address of the DCAP server. Default is "127.0.0.1".
                - `port`: The port number for the DCAP server. Default is 9443.
                - `secure`: A boolean value indicating whether to use a secure connection. Default is True.
                - `username`: The username for the DCAP server. Default is None.
                - `password`: The password for the DCAP server. Default is None.

                Please refer `connect_to <https://taf-sw-dcap-rd.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/\
                interface.html#taf.sw.dcap.rd.interface.rd.connect_to>`_ keyword for other supported parameters.

        Returns:
            None
        """
        self._create_emil_converter(name=name, file_path_pattern=file_path_pattern, server_filter=server_filter,
                                    client_filter=client_filter, output_type=output_type,
                                    output_directory=output_directory, uploading_timeout=uploading_timeout,
                                    decoding_timeout=decoding_timeout, dcap=dcap, converter_type='call',
                                    trace_id=trace_id)
